function translate(text){
 if(currentLanguage()==='ru'){const exact={'Site URL':'Адрес сайта','Payment method':'Метод оплаты','Account ID':'ID аккаунта','Login':'Логин','Password':'Пароль','Account ID USD':'ID USD-аккаунта','Login USD':'Логин USD','Password USD':'Пароль USD'};if(exact[text])return exact[text];return text.replace(/Turkey|Azerbaijan|Chile|Canada|Guatemala|Kazakhstan|Bolivia|Uzbekistan|India|Kyrgyzstan|Bangladesh|Mexico|Ecuador|Honduras|Tajikistan|Nigeria|Kenya|Congo|Russia/g,x=>russianRegions[x]);}
 const index=currentLanguage()==='en'?0:1;
 if(translations[text])return translations[text][index];
 return text.replace(new RegExp(extraPhrasePattern+'|'+paymentTitleFeatures.map(x=>x[1]).join('|')+'|QR: оплата по сохранённым платёжным данным|, установить PWA приложение через меню браузера и открыть установленное PWA приложение\\.|PWA приложение|'+phraseRE.source,'g'),x=>translations[x][index]);
}

/** Replace the placeholder tokens with the real operator-entered values. */
function localise(text, protectedValues) {
  return translate(text).replace(/⟦VALUE(\d+)⟧/g, (_, i) => protectedValues[Number(i)]);
}

