/**
 * Deposit case matrix.
 *
 * Rules preserved from the legacy generator (do not "simplify" without a
 * requirement change):
 *  - wallet flows only exist for Apple Pay / Google Pay;
 *  - two saved-payment scenarios (after timer, after cancel) are both kept;
 *  - the cashier-return precheck runs once per platform, in its first case;
 *  - platform coverage counters reset on every generation;
 *  - a receipt adds valid/invalid/no-receipt variants without dropping cases.
 */
function generateWalletCases(wallet) {
  $('message').textContent = '';
  const region = currentRegion();
  const full = true;
  const change = $('amountChange').value === 'yes';
  const com = $('license').value === 'com';
  const qr = checked('qr');
  const receipt = checked('receipt');
  const cases = [];
  const used = new Set();
  const cashierReturnPlatforms = new Set();
  const browsers = platformList(region);
  const amount = val('amount', 'AMOUNT');
  const scanners = $('qrScanner').value === 'both' ? ['camera', 'app'] : [$('qrScanner').value];
  let scanIndex = 0;

  function pay(steps, platform, paid, currency, card) {
    if (wallet && !qr && !checked('oneClick')) {
      steps.push(
        'Открыть платёжное окно ' + wallet + '.',
        'Выбрать карту ' + card + ' в кошельке.',
        'Проверить платёжные данные и выполнить оплату на сумму ' + paid + ' ' + currency + '.',
        'Подтвердить оплату в кошельке. Убедиться, что результат оплаты отображается на исходной платформе.',
      );
      return;
    }
    if (qr && isDesktop(platform)) {
      const scanner = scanners[scanIndex++ % scanners.length];
      steps.push('Оставить QR-код открытым на экране компьютера.');
      steps.push(scanner === 'camera'
        ? 'Отсканировать QR-код обычной камерой телефона и открыть распознанную ссылку.'
        : 'Открыть платёжное приложение на телефоне и отсканировать QR-код встроенной камерой приложения.');
    } else if (qr && $('qrMobile').value === 'download') {
      steps.push(
        'Скачать QR-код на мобильное устройство.',
        'Открыть платёжное приложение и загрузить сохранённое изображение QR для распознавания.',
      );
    } else if (!isDesktop(platform) && (qr || checked('oneClick'))) {
      steps.push(
        'Нажать кнопку перехода в платёжное приложение.',
        'Убедиться, что именно по кнопке открылось нужное платёжное приложение.',
      );
    } else if (!wallet) {
      steps.push('Скопировать необходимые платёжные реквизиты и использовать их для перевода.');
    }
    if (wallet) {
      steps.push('Открыть платёжное окно ' + wallet + '.', 'Выбрать карту ' + card + ' в кошельке.');
    }
    steps.push('Проверить платёжные данные и выполнить оплату на сумму ' + paid + ' ' + currency + '.');
    if (wallet) {
      steps.push('Подтвердить оплату в кошельке. Убедиться, что результат оплаты отображается на исходной платформе.');
    }
  }

  function add(platform, kind, usd = false) {
    const card = !wallet ? ''
      : $('cardNetwork').value === 'both'
        ? (cases.length === 0 ? 'Visa' : 'Mastercard')
        : $('cardNetwork').value === 'visa' ? 'Visa' : 'Mastercard';

    let sum = amount;
    if (kind === 'over') {
      sum = val(usd ? 'usdOverRequest' : 'overRequest', usd ? 'USD_OVER_REQUEST_AMOUNT' : 'OVER_REQUEST_AMOUNT');
    } else if (kind === 'under') {
      sum = val(usd ? 'usdUnderRequest' : 'underRequest', usd ? 'USD_UNDER_REQUEST_AMOUNT' : 'UNDER_REQUEST_AMOUNT');
    } else if (usd) {
      sum = val('usdAmount', 'USD_AMOUNT');
    }
    const currency = usd ? 'USD' : region.currency;

    let paid = sum;
    if (kind === 'over') paid = val(usd ? 'usdOverPaid' : 'overPaid', usd ? 'USD_OVERPAY_ACTUAL_AMOUNT' : 'OVERPAY_ACTUAL_AMOUNT');
    if (kind === 'under') paid = val(usd ? 'usdUnderPaid' : 'underPaid', usd ? 'USD_UNDERPAY_ACTUAL_AMOUNT' : 'UNDERPAY_ACTUAL_AMOUNT');

    const checkCashierReturn = cases.length > 0
      && $('integration').value === 'HPP'
      && checked('returnToCashier')
      && !cashierReturnPlatforms.has(platform);

    const steps = baseSteps(platform, usd, checkCashierReturn);
    let pre = wallet ? 'На тестовом устройстве настроен ' + wallet + ' и добавлена карта ' + card + '.' : '';
    if (checkCashierReturn) cashierReturnPlatforms.add(platform);

    const returnsFromWallet = !isDesktop(platform)
      && ((qr && $('qrMobile').value === 'button') || checked('oneClick'))
      && (kind === 'expiry' || kind === 'before' || (qr && $('qrMobile').value === 'download'));

    if (returnsFromWallet) {
      steps.push(
        'Нажать кнопку перехода в платёжное приложение.',
        'Убедиться, что именно по кнопке открылось нужное платёжное приложение.',
        'Не выполнять оплату. Вернуться из платёжного приложения к исходной платёжной форме на тестируемой платформе и убедиться, что заявка доступна.',
      );
    }

    if (wallet && !qr && !checked('oneClick') && (kind === 'expiry' || kind === 'before')) {
      steps.push(
        'Открыть платёжное окно ' + wallet + '.',
        'Выбрать карту ' + card + ' в кошельке.',
        'Не подтверждать оплату в кошельке.',
        kind === 'expiry' ? 'Дождаться окончания таймера заявки.' : 'Вернуться к заявке и отменить её кнопкой отмены.',
        'Попробовать подтвердить оплату исходной заявки в кошельке после отмены или окончания таймера. Не создавать новую заявку. Если оплата недоступна, зафиксировать причину и проверить отсутствие списания; оставшиеся шаги оплаты не выполнять.',
      );
    } else if (kind === 'expiry' || kind === 'before') {
      pre += (pre ? ' ' : '') + 'Сохранить платёжные данные ДО '
        + (kind === 'expiry' ? 'окончания таймера' : 'отмены заявки') + '.';
      const savedHint = qr ? ' и QR-код'
        : checked('oneClick') && !isDesktop(platform) ? ' и платёжную ссылку' : '';
      steps.push('До ' + (kind === 'expiry' ? 'окончания таймера' : 'отмены заявки')
        + ' сохранить реквизиты' + savedHint + ' для последующей оплаты.');
      steps.push(kind === 'expiry'
        ? 'Не оплачивать заявку до окончания таймера. Дождаться его завершения и показать состояние страницы.'
        : 'Отменить заявку кнопкой отмены и подтвердить отмену, если требуется.');
      steps.push('После ' + (kind === 'expiry' ? 'окончания таймера' : 'отмены')
        + ' выполнить оплату на сумму ' + paid + ' ' + currency
        + ' по заранее сохранённым платёжным данным. Если оплата недоступна, зафиксировать причину.');
    } else {
      pay(steps, platform, paid, currency, card);
    }

    if (kind === 'over' || kind === 'under') {
      steps.push('Фактическая сумма должна быть ' + (kind === 'over' ? 'больше' : 'меньше') + ' суммы заявки.');
    }

    const h2h = $('integration').value === 'H2H';
    const special = ['after', 'before', 'expiry'].includes(kind);
    if (kind === 'after') {
      steps.push('Сразу после перевода вернуться ' + (h2h ? 'в кассу' : 'к платёжной форме провайдера')
        + ' и нажать кнопку отмены. Подтвердить отмену, если требуется. Если кнопка уже недоступна, показать это на видео.');
    } else {
      steps.push(h2h ? 'Вернуться в кассу.' : 'Вернуться к платёжной форме провайдера.');
    }

    const receiptIndex = steps.length;
    if (kind === 'expiry') {
      steps.push('После фактической оплаты подождать и убедиться, что форма с истёкшим таймером не реагирует на оплату. Затем самостоятельно вернуться в кассу.');
    } else if (h2h) {
      steps.push(special
        ? 'Если после отмены или окончания таймера кнопка «Я оплатил» остаётся доступна, нажать её. Если кнопка недоступна, показать состояние кассы на видео.'
        : 'Нажать кнопку «Я оплатил».');
    } else {
      if (!special) steps.push('Нажать кнопку подтверждения оплаты, если она предусмотрена.');
      steps.push('Дождаться завершения обработки оплаты и возврата в кассу.');
    }

    const titles = {
      regular: 'успешный депозит',
      over: 'переплата',
      under: 'недоплата',
      expiry: 'оплата после окончания таймера',
      before: 'отмена, затем оплата',
      after: 'оплата, затем отмена',
    };
    const features = paymentTitleFeatures.filter(([step]) => steps.includes(step));
    const paymentFeatures = features.map((feature) => (qr && feature === paymentTitleFeatures[3] ? 'QR: ' : '') + feature[1]);
    if (qr && (kind === 'expiry' || kind === 'before')) paymentFeatures.push('QR: оплата по сохранённым платёжным данным');
    const paymentFeature = paymentFeatures.join(' + ');

    cases.push({
      title: (wallet ? wallet + ' / ' + card + ' - ' : '') + platform + ' - ' + (usd ? 'USD + ' : '') + titles[kind] + (paymentFeature ? ' + ' + paymentFeature : ''),
      platform, sum, currency, usd, steps, pre, receiptIndex, kind, card,
    });
    used.add(platform);
  }

  if (wallet) {
    browsers.forEach((platform) => add(platform, 'regular'));
    if (change) {
      add(browsers[0], 'over', com);
      add(browsers[1], 'under');
    } else if (com) {
      add(browsers[0], 'regular', true);
    }
    if (checked('timer')) add(browsers[0], 'expiry');
    if (checked('cancel')) {
      add(browsers[0], 'before');
      add(browsers[1], 'after');
    }
  } else {
    add(browsers[0], 'regular');
    const apps = licenseApps();
    const appPlatform = apps.pwa ? 'PWA приложение' : apps.native ? PLATFORM_NATIVE : null;
    if (change) add(appPlatform || browsers[0], full ? 'over' : 'under', com);
    else if (com) add(appPlatform || browsers[0], 'regular', true);
    if (full) {
      if (appPlatform && !used.has(appPlatform)) add(appPlatform, 'regular');
      if (apps.native && !used.has(PLATFORM_NATIVE)) add(PLATFORM_NATIVE, 'regular');
      if (apps.webview) add(PLATFORM_WEBVIEW, change ? 'under' : 'regular');
      else if (change) add(browsers[0], 'under');
      const scenarios = [];
      if (checked('timer')) scenarios.push('expiry');
      if (checked('cancel')) scenarios.push('before', 'after');
      scenarios.forEach((kind) => {
        // Reserve desktop QR coverage for an ordinary payment to exercise scanning.
        const candidates = browsers.filter((platform) => !qr || !isDesktop(platform));
        add(candidates.find((platform) => !used.has(platform)) || candidates[0], kind);
      });
      browsers.forEach((platform) => { if (!used.has(platform)) add(platform, 'regular'); });
    }
  }

  if ($('integration').value === 'HPP' && checked('returnToCashier') && !cashierReturnPlatforms.has(browsers[0])) {
    add(browsers[0], 'regular');
  }

  if (qr) {
    const desktop = wallet ? browsers.find(isDesktop) : 'Desktop ' + region.desktop[0];
    while (scanIndex < scanners.length) add(desktop, 'regular');
  }

  if (receipt) {
    cases[0].steps.splice(cases[0].receiptIndex, 0, 'Загрузить валидный чек выполненного перевода и убедиться, что он принят.');
    let eligible = cases.filter((item, i) => i > 0 && ['regular', 'over', 'under'].includes(item.kind));
    while (eligible.length < 3) {
      add(wallet ? browsers[browsers.length - 1] : 'Desktop ' + region.desktop[0], 'regular');
      eligible = cases.filter((item, i) => i > 0 && ['regular', 'over', 'under'].includes(item.kind));
    }
    // Keep underpayment with a valid receipt; assign the no-receipt flow elsewhere.
    const without = eligible.find((item) => item.kind === 'over') || eligible.find((item) => item.kind === 'regular');
    const invalid = eligible.find((item) => item !== without && item.kind === 'regular' && isDesktop(item.platform) && !item.usd)
      || eligible.find((item) => item !== without && item.kind === 'regular' && !item.usd)
      || eligible.find((item) => item !== without && item.kind !== 'under');
    eligible.forEach((item) => {
      if (item === without) {
        // Remove form confirmation and waiting: return to cashdesk without a receipt.
        item.steps = item.steps.slice(0, item.receiptIndex - 1);
        item.steps.push('После оплаты, не загружая чек, вернуться в кассу.');
        item.title += ' + без загрузки обязательного чека';
      } else if (item === invalid) {
        item.steps = item.steps.slice(0, item.receiptIndex);
        item.steps.push('Загрузить невалидный чек - чек от другой операции, не соответствующий текущему платежу.');
        item.steps.push('Попробовать подтвердить оплату'
          + ($('integration').value === 'H2H'
            ? ' кнопкой «Я оплатил»'
            : ' кнопкой подтверждения на странице провайдера, если она предусмотрена')
          + '. Показать на видео реакцию формы и отображаемое сообщение.');
        item.steps.push('Не заменять чек валидным. Вернуться в кассу.');
        item.title = item.title.replace('успешный депозит', 'оплата') + ' + невалидный чек';
      } else {
        item.steps.splice(item.receiptIndex, 0, 'Загрузить валидный чек выполненного перевода и убедиться, что он принят.');
        item.title += ' + валидный чек';
      }
    });
  }

  if (wallet === 'Google Pay') {
    // Cover the signed-out Google state once on desktop; site login is independent.
    const signedOut = cases.find((item) => item.platform === 'Desktop Chrome' && item.kind === 'regular');
    cases.forEach((item) => {
      if (item === signedOut) {
        item.pre += ' Пользователь не авторизован в аккаунте Google в тестируемом браузере. Авторизация на сайте выполняется отдельно.';
        item.title += ' + без авторизации в Google';
        const index = item.steps.findIndex((step) => step === 'Открыть платёжное окно Google Pay.');
        item.steps.splice(index + 1, 0, 'Проверить предложение войти в аккаунт Google. Выполнить вход в тестовый Google-аккаунт и продолжить оплату выбранной картой. Если продолжение недоступно, зафиксировать результат и не выполнять оставшиеся шаги оплаты.');
      } else {
        item.pre += ' Пользователь авторизован в аккаунте Google, используемом для Google Pay.';
      }
    });
  }

  // Every return-to-cashier step must be followed by a pending-popup check.
  cases.forEach((item) => {
    item.steps = item.steps.flatMap((step, i) => {
      const returnsToCashier = /вернуться в кассу|возврата в кассу/i.test(step);
      const alreadyChecked = (item.steps[i + 1] || '').includes('pending popup');
      return returnsToCashier && !alreadyChecked
        ? [step, 'Убедиться, что касса открыта и пользователю отображается pending popup.']
        : [step];
    });
  });

  return cases.map((item) => ({
    title: item.title,
    text: header(item.platform, item.sum, item.currency, { usd: item.usd })
      .concat(wallet ? ['Wallet: ' + wallet, 'Card: ' + item.card] : [])
      .join('\n')
      + (item.pre ? '\n\nПредусловие: ' + item.pre : '')
      + '\n\n' + item.steps.map((step, i) => 'Шаг ' + (i + 1) + ' - ' + step).join('\n')
      + '\n\nПросьба записать видео полного флоу от шага 1 до шага ' + item.steps.length + '.'
      + (qr && isDesktop(item.platform)
        ? ' Просим включить в видеозапись экран мобильного телефона: момент сканирования QR-кода и весь последующий процесс оплаты.'
        : ''),
  }));
}

// ---- generator/cases/index.js ----------------------------------------
/**
 * Case-generation wiring.
 *
 * `generate.js` owns the entry point and payout cases, `wallet.js` owns the
 * deposit matrix. Both need each other's helpers, so the link is injected here
 * exactly once instead of importing each other (which would be a cycle).
 */

__setWalletCases(generateWalletCases);

// ---- generator/cases/payout.js ---------------------------------------
/**
 * Payout amounts are integers in local currency. A 25% commission must leave
 * a fractional value, so requests divisible by 4 are rejected.
 */
const payoutInteger = (raw) => {
  if (!/^\d{1,6}$/.test(raw.trim())) return null;
  const value = Number(raw);
  return Number.isSafeInteger(value) && value > 0 && value <= Math.floor(Number.MAX_SAFE_INTEGER / 100)
    ? value
    : null;
};

/** Smallest request near amount/0.75 whose 25% commission lands on a fraction. */
function suggestedPayoutAmount() {
  const amount = payoutInteger($('payoutAmount').value);
  if (amount === null) return '';
  const near = Math.min(999999, Math.floor(amount / 0.75));
  const candidates = [near - 1, near, near + 1, near + 2]
    .filter((value) => value > 0 && value <= 999999 && value % 4 !== 0);
  // On an equal distance prefer the larger net amount.
  candidates.sort((a, b) => Math.abs(a * 3 - amount * 4) - Math.abs(b * 3 - amount * 4) || b - a);
  return String(candidates[0]);
}

/** Validation message for the payout amount fields, or an empty string. */
function payoutAmountError() {
  const ids = ['payoutAmount', 'payoutFeeAmount', ...($('license').value === 'com' ? ['usdAmount'] : [])];
  for (const id of ids) {
    if ($(id).value.trim() && payoutInteger($(id).value) === null) {
      return 'Сумма заявки должна быть положительным целым числом.';
    }
  }
  const fee = payoutInteger($('payoutFeeAmount').value);
  return fee !== null && fee % 4 === 0
    ? 'После удержания 25% получится целая сумма. Выберите сумму заявки, не кратную 4.'
    : '';
}

/** Recompute the fee request unless the operator typed a manual value. */
function updatePayoutAmount() {
  if (!state.payoutFeeManual) $('payoutFeeAmount').value = suggestedPayoutAmount();
  const error = payoutAmountError();
  $('payoutWarning').textContent = error ? translate(error) : '';
}

/** Apply integration/licence/wallet/region visibility rules to the form. */
function updateUI() {
  const integration = $('integration').value;
  const wallet = walletName();
  const google = $('wallet').value === 'google';

  $('h2hNotice').classList.toggle('hidden', integration !== 'H2H');
  $('cardNetworkWrap').classList.toggle('hidden', !wallet);
  $('walletSettings').classList.toggle('hidden', !wallet);
  $('googleMethodModeWrap').classList.toggle('hidden', !google);
  $('googleMethodHint').classList.toggle('hidden', !google);
  $('googleMethodMode').disabled = !google;
  $('nativeMethodWrap').classList.toggle('hidden', !google || $('googleMethodMode').value !== 'separate');
  $('returnToCashierWrap').classList.toggle('hidden', integration !== 'HPP');
  $('returnToCashier').disabled = integration !== 'HPP';

  const region = currentRegion();
  $('regionInfo').innerHTML =
    'Валюта: <b>' + region.currency + '</b><br>Android: ' + region.android.join(', ') +
    '<br>iOS: ' + region.ios.join(', ') + '<br>Desktop: ' + region.desktop.join(', ');

  $('qrSettings').classList.toggle('hidden', !checked('qr'));

  const apps = licenseApps();
  const extra = [];
  if (apps.webview) extra.push('WebView');
  if (apps.native) extra.push('Нативное приложение');
  if (apps.pwa) extra.push('PWA приложение');
  if (extra.length) $('regionInfo').innerHTML += '<br>Дополнительные платформы: ' + extra.join(', ');

  if (wallet) {
    $('regionInfo').innerHTML =
      'Валюта: <b>' + region.currency + '</b><br>' + wallet + ': ' + platformList(region).join(', ');
  }

  $('comBox').classList.toggle('hidden', $('license').value !== 'com');
  // Over/underpayment actual amounts exist only when the amount may change.
  const amountChange = $('amountChange').value === 'yes';
  $('usdOverWrap').classList.toggle('hidden', !amountChange);
  $('usdUnderWrap').classList.toggle('hidden', !amountChange);
  $('overWrap').classList.toggle('hidden', false);
  $('overRequestWrap').classList.toggle('hidden', false);
  $('usdOverRequestWrap').classList.toggle('hidden', !amountChange);
  $('usdUnderRequestWrap').classList.toggle('hidden', !amountChange);

  const payout = integration === 'payout';
  ['walletWrap', 'amountChangeWrap', 'amountWrap', 'underPaidWrap', 'underRequestWrap',
    'overWrap', 'overRequestWrap', 'depositFeatures']
    .forEach((id) => $(id).classList.toggle('hidden', payout));
  ['payoutAmountWrap', 'payoutFeeAmountWrap', 'payoutHint']
    .forEach((id) => $(id).classList.toggle('hidden', !payout));

  if (payout) {
    ['walletSettings', 'nativeMethodWrap', 'usdOverWrap', 'usdUnderWrap',
      'usdOverRequestWrap', 'usdUnderRequestWrap']
      .forEach((id) => $(id).classList.add('hidden'));
    $('regionInfo').textContent = translate('Валюта:') + ' ' + region.currency + ' · Device: any';
    updatePayoutAmount();
  }
}

// ---- generator/cases/render.js ---------------------------------------
const copyStatusTimers = new WeakMap();

/** Read the editable case card back into a plain record. */
function readCase(card) {
  return {
    title: card.querySelector('h3').textContent,
    text: card.querySelector('pre').textContent,
    comment: card.querySelector('.case-comment').value.trim(),
    request_text: card.querySelector('.case-request').value.trim(),
  };
}

/** Clipboard text for one card, matching the Slack message layout. */
function caseCopyText(card) {
  const item = readCase(card);
  return item.title + '\n\n' + item.text
    + (item.comment ? '\n\nДополнительная информация:\n' + item.comment : '');
}

const caseLabel = () =>
  state.language === 'en' ? 'Copy case' : state.language === 'uk' ? 'Копіювати кейс' : 'Копировать кейс';

function element(tag, { className, text } = {}) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function statusLine(options = {}) {
  const node = element('div', { className: 'case-copy-status' });
  node.setAttribute('role', 'status');
  node.setAttribute('aria-live', 'polite');
  Object.assign(node.style, options);
  return node;
}

function textarea({ className, rows = 3, maxLength, placeholder, style }) {
  const node = element('textarea', { className });
  node.rows = rows;
  node.placeholder = placeholder || '';
  if (maxLength) node.maxLength = maxLength;
  Object.assign(node.style, style);
  return node;
}

/** Render the generated cases into the output container. */
function renderCases(cases) {
  const output = $('output');
  output.innerHTML = '';
  $('count').textContent = String(cases.length);

  cases.forEach((item, index) => {
    const card = element('div', { className: 'case' });
    const heading = element('h3', { text: (index + 1) + '. ' + item.title });
    const body = element('pre', { text: item.text });

    const head = element('div', { className: 'case-head' });
    head.style.flexWrap = 'wrap';

    const copyButton = element('button', { className: 'secondary copy-case', text: caseLabel() });
    copyButton.type = 'button';
    copyButton.setAttribute('aria-label', caseLabel() + ' ' + (index + 1));

    const slackButton = element('button', {
      className: 'send-case-slack',
      text: translate('Отправить в Slack'),
    });
    slackButton.type = 'button';
    slackButton.setAttribute('aria-label', translate('Отправить в Slack кейс ') + (index + 1));

    const editButton = element('button', { className: 'secondary', text: translate('Редактировать') });
    editButton.type = 'button';
    editButton.setAttribute('aria-pressed', 'false');
    editButton.addEventListener('click', () => {
      const editing = editButton.getAttribute('aria-pressed') !== 'true';
      editButton.setAttribute('aria-pressed', String(editing));
      editButton.textContent = translate(editing ? 'Готово' : 'Редактировать');
      [heading, body].forEach((node) => {
        node.contentEditable = editing ? 'plaintext-only' : 'false';
        node.style.outline = editing ? '2px solid #90b9fa' : '';
      });
      if (editing) body.focus();
    });

    const status = statusLine();

    const requestLabel = element('label', {
      text: translate('Обращение в Slack для этого кейса'),
    });
    const request = textarea({
      className: 'case-request',
      maxLength: 2000,
      style: {
        width: '100%',
        boxSizing: 'border-box',
        padding: '12px',
        border: '1px solid #bdccdc',
        borderRadius: '7px',
        font: 'inherit',
        resize: 'vertical',
      },
    });
    request.value = [
      translate($('integration').value === 'payout' ? 'Просьба провести тест выплаты.' : 'Просьба провести тест депозита.'),
      item.title,
    ].filter(Boolean).join('\n');
    requestLabel.appendChild(request);

    const commentLabel = element('label', {
      text: translate('Дополнительные инструкции (необязательно)'),
    });
    commentLabel.style.marginTop = '16px';
    const comment = textarea({
      className: 'case-comment',
      placeholder: translate('Будут отправлены в тред под описанием кейса'),
      style: {
        width: '100%',
        padding: '12px',
        border: '1px solid #bdccdc',
        borderRadius: '7px',
        font: 'inherit',
        resize: 'vertical',
      },
    });
    commentLabel.appendChild(comment);

    copyButton.addEventListener('click', () => copyText(caseCopyText(card), status, card));
    slackButton.addEventListener('click', () => sendSingleCase(card, status));

    head.append(heading, editButton, copyButton, slackButton);
    card.append(head, status, requestLabel, body, commentLabel);
    output.appendChild(card);
  });
}

/** Copy the current case text and flash a short confirmation. */
async function copyText(text, status, card) {
  try {
    await navigator.clipboard.writeText(text);
    status.textContent = translate('Текст кейса скопирован.');
  } catch {
    status.textContent = translate('Не удалось скопировать текст.');
  }
  const previous = copyStatusTimers.get(card);
  if (previous) clearTimeout(previous);
  copyStatusTimers.set(card, setTimeout(() => { status.textContent = ''; }, 4000));
}

async function sendSingleCase(card, status) {
  status.textContent = translate('Отправляем кейс в Slack...');
  try {
    const response = await fetch('/slack/send-cases', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        region: $('region').value,
        ...mentionPayload(),
        cases: [readCase(card)],
      }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.detail || 'Slack send failed');
    status.textContent = translate('Кейс отправлен в Slack.');
  } catch (error) {
    status.textContent = translate('Ошибка отправки в Slack: ') + error.message;
  }
}

// ---- generator/ui/language.js ----------------------------------------
const SKIP_SELECTOR = [
  'script', 'style',
  '[data-id="output"]', '[data-id="message"]', '[data-id="regionInfo"]',
  '[data-id="mentionList"]', '[data-id="mentionStatus"]',
].join(',');

/** Text nodes translated in place when the language changes. */
const translatableNodes = [];
/** Image thumbnails whose alt text is translated too. */
const thumbnails = [];

/** Collect the static DOM that `refreshLanguage` rewrites. Call once on start. */
function cacheStaticNodes() {
  const root = state.root;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement.closest(SKIP_SELECTOR)) continue;
    if (node.nodeValue.trim()) translatableNodes.push([node, node.nodeValue]);
  }
  root.querySelectorAll('.thumbnail img').forEach((img) => thumbnails.push([img, img.alt]));
}

/** Re-apply the active language to the whole form. */
function refreshLanguage() {
  const root = state.root;
  root.lang = state.language;
  translatableNodes.forEach(([node, original]) => {
    const core = original.trim();
    node.nodeValue = original.replace(core, translate(core));
  });
  thumbnails.forEach(([img, alt]) => { img.alt = translate(alt); });
  root.querySelectorAll('[data-lang]').forEach((button) => {
    button.setAttribute('aria-pressed', String(button.dataset.lang === state.language));
  });
  root.querySelector('.close-image').setAttribute('aria-label', translate('Закрыть изображение'));
  updateUI();
  root.querySelector('[data-id="regionInfo"]').innerHTML = translate(root.querySelector('[data-id="regionInfo"]').innerHTML);
}

// ---- generator/ui/accounts.js ----------------------------------------
/** Region account catalog operations against the local API. */

function accountError(error) {
  state.root.querySelector('.account-save-status').textContent = error.message;
}

const fieldsFor = (kind) => (kind === 'usd'
  ? ['usdAccount', 'usdLogin', 'usdPassword']
  : ['account', 'login', 'password']);

/** Replace every saved-user dropdown with the catalog for the current region. */
function setAccountOptions(accounts) {
  state.accountOptions = accounts;
  state.accountRegion = $('region').value;
  for (const select of state.root.querySelectorAll('.account-picker')) {
    const ids = fieldsFor(select.dataset.accountKind);
    select.replaceChildren(new Option('Новый пользователь · ввести вручную', ''));
    for (const account of accounts) {
      select.add(new Option(`${account.name} · ${account.account_id || account.login || 'без ID'}`, account.id));
    }
    const match = accounts.find((account) => [account.account_id, account.login, account.password]
      .every((value, i) => value === $(ids[i]).value));
    select.value = match?.id || '';
  }
}

/** Load the owner's catalog for a region; stale responses are ignored. */
async function loadAccounts() {
  const revision = ++state.accountRequest;
  const region = $('region').value;
  const response = await fetch('/api/tasks/accounts?region=' + encodeURIComponent(region));
  if (!response.ok) throw new Error('Не удалось загрузить пользователей региона');
  const accounts = await response.json();
  if (revision === state.accountRequest && region === $('region').value) setAccountOptions(accounts);
  return accounts;
}

/** Wire the saved-user dropdowns to the credential inputs. */
function bindAccountPickers() {
  for (const select of state.root.querySelectorAll('.account-picker')) {
    const ids = fieldsFor(select.dataset.accountKind);

    select.addEventListener('change', () => {
      const account = state.accountOptions.find((item) => item.id === select.value);
      const values = account ? [account.account_id, account.login, account.password] : ['', '', ''];
      ids.forEach((id, i) => { $(id).value = values[i]; });
      $(ids[0]).dispatchEvent(new Event('input', { bubbles: true }));
      select.value = account?.id || '';
    });

    for (const id of ids) {
      $(id).addEventListener('input', () => {
        const account = state.accountOptions.find((item) => [item.account_id, item.login, item.password]
          .every((value, i) => value === $(ids[i]).value));
        select.value = account?.id || '';
      });
    }
  }
}

/** Persist the credentials typed into the form for the current region. */
async function saveStandaloneAccounts() {
  const button = state.root.querySelector('.standalone-account-save');
  button.disabled = true;
  try {
    const users = [];
    for (const kind of ['main', 'usd']) {
      if (kind === 'usd' && $('license').value !== 'com') continue;
      const ids = fieldsFor(kind);
      const values = ids.map((id) => $(id).value);
      if (!values.some(Boolean)) continue;
      const existing = state.accountOptions.find((item) => [item.account_id, item.login, item.password]
        .every((value, i) => value === values[i]));
      users.push({
        id: existing?.id || crypto.randomUUID(),
        name: existing?.name || values[1] || values[0] || 'Пользователь',
        kind,
        account_id: values[0],
        login: values[1],
        password: values[2],
      });
    }
    const response = await fetch('/api/tasks/accounts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ region: $('region').value, test_accounts: users }),
    });
    const result = await response.json();
    if (!response.ok) throw new Error(typeof result.detail === 'string' ? result.detail : 'Проверьте данные пользователя');
    setAccountOptions(result.accounts);
    state.root.querySelector('.account-save-status').textContent = 'Пользователи региона сохранены';
  } catch (error) {
    accountError(error);
  } finally {
    button.disabled = false;
  }
}

/** Copy a saved user's credentials into the form, for workspace sync. */
function syncAccountFields(previous, next) {
  for (const ids of [['account', 'login', 'password'], ['usdAccount', 'usdLogin', 'usdPassword']]) {
    const keys = ['account_id', 'login', 'password'];
    if (ids.every((id, i) => $(id).value === previous[keys[i]])) {
      ids.forEach((id, i) => { $(id).value = next[keys[i]]; });
    }
  }
}

// ---- generator/ui/events.js ------------------------------------------
/** Generate cases from the current form, honouring the workspace gates. */
function generate() {
  if (state.workspaceHooks?.beforeGenerate && !state.workspaceHooks.beforeGenerate()) return;
  try {
    state.protectedValues = [];
    state.protectValues = true;
    let cases;
    try {
      cases = generateCases();
    } finally {
      state.protectValues = false;
    }

    const kinds = cases.map((item) => (item.usd || /^USD -/.test(item.title) ? 'usd' : 'main'));
    cases = cases.map((item) => ({ title: localise(item.title, state.protectedValues), text: localise(item.text, state.protectedValues) }));
    renderCases(cases);
    state.generated = true;

    if (state.workspaceHooks) {
      state.workspaceHooks.onGenerated(
        undefined,
        window.qaGenerator.cases().map((item, i) => ({ ...item, account_kind: kinds[i] })),
      );
    }
    $('message').textContent = '';
  } catch (error) {
    state.protectValues = false;
    $('message').textContent = translate('Ошибка генератора: ') + error.message;
  }
}

/** Copy all cases as one text blob. */
function copyAllCases() {
  const text = [...state.root.querySelectorAll('.case')].map(caseCopyText).join('\n\n================\n\n');
  if (!text) {
    $('message').textContent = translate('Сначала сгенерируйте кейсы.');
    return;
  }
  copyText(text, $('message'), $('output'));
}

/** Send every case (optionally skipping the first) to Slack. */
async function sendCasesToSlack(skipFirst = false) {
  const caseNodes = [...state.root.querySelectorAll('.case')];
  if (!caseNodes.length) {
    $('message').textContent = translate('Сначала сгенерируйте кейсы.');
    return;
  }
  const cases = caseNodes.slice(skipFirst ? 1 : 0).map((node) => readCaseFromNode(node));
  if (!cases.length) {
    $('message').textContent = translate('Нет кейсов для отправки после первого.');
    return;
  }
  $('message').textContent = translate('Отправляем кейсы в Slack...');
  try {
    const response = await fetch('/slack/send-cases', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ region: $('region').value, cases,
        operation: $('integration').value === 'payout' ? 'payout' : 'deposit' }),
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.detail || 'Slack send failed');
    $('message').textContent = translate('Отправлено в Slack: ') + data.sent + translate(' кейс(ов).');
  } catch (error) {
    $('message').textContent = translate('Ошибка отправки в Slack: ') + error.message;
  }
}

function readCaseFromNode(card) {
  return {
    title: card.querySelector('h3').textContent,
    text: card.querySelector('pre').textContent,
    comment: card.querySelector('.case-comment').value.trim(),
    request_text: card.querySelector('.case-request').value.trim(),
  };
}

/** Number inputs reject anything that is not 0–6 digits. */
function bindAmountInputs() {
  amountInputIds.forEach((id) => {
    const input = $(id);
    let previous = input.value;
    input.addEventListener('input', () => {
      if (!validAmountInput(input.value)) {
        input.value = validAmountInput(previous) ? previous : '';
        $('message').textContent = translate('Введите целое число: не более 6 цифр.');
      } else {
        previous = input.value;
      }
    });
    input.addEventListener('beforeinput', () => { previous = input.value; });
    input.addEventListener('paste', (event) => {
      const text = event.clipboardData.getData('text');
      const next = input.value.slice(0, input.selectionStart) + text + input.value.slice(input.selectionEnd);
      if (!validAmountInput(next)) {
        event.preventDefault();
        $('message').textContent = translate('Введите целое число: не более 6 цифр.');
      }
    });
  });
}

/** Image lightbox for the Cashdesk screenshots. */
function bindLightbox() {
  const dialog = state.root.querySelector('dialog');
  let opener = null;
  state.root.querySelectorAll('.thumbnail').forEach((button) => {
    button.addEventListener('click', () => {
      opener = button;
      const image = button.querySelector('img');
      const large = dialog.querySelector('img');
      large.src = image.src;
      large.alt = image.alt;
      dialog.showModal();
    });
  });
  dialog.querySelector('button').addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', (event) => { if (event.target === dialog) dialog.close(); });
  dialog.addEventListener('close', () => { if (opener) opener.focus(); });
}

/** Region switch: confirm, clear credentials and reload the catalog. */
function bindRegionSwitch() {
  $('region').addEventListener('input', () => {
    const previous = state.accountRegion;
    const region = $('region').value;
    if (previous === region) return;
    if (state.workspaceHooks?.beforeRegionChange && !state.workspaceHooks.beforeRegionChange(previous)) {
      $('region').value = previous;
      updateUI();
      return;
    }
    state.accountRegion = region;
    for (const id of ['account', 'login', 'password', 'usdAccount', 'usdLogin', 'usdPassword']) $(id).value = '';
    setAccountOptions([]);
    if (state.workspaceHooks?.onRegionChange) state.workspaceHooks.onRegionChange(region);
    else loadAccounts().catch(accountErrorBridge);
  });
}

function accountErrorBridge(error) {
  state.root.querySelector('.account-save-status').textContent = error.message;
}

/** Attach every DOM listener that the legacy generator registered inline. */
function bindEvents() {
  bindAmountInputs();

  $('payoutFeeAmount').addEventListener('input', () => { state.payoutFeeManual = true; });
  $('payoutAmount').addEventListener('input', () => { updatePayoutAmount(); });
  $('generate').addEventListener('click', generate);

  $('sendSlack').addEventListener('click', () => sendCasesToSlack());
  $('sendSlackExceptFirst').addEventListener('click', () => sendCasesToSlack(true));
  $('copyAll').addEventListener('click', copyAllCases);

  // Any form change invalidates generated output until the next generation.
  state.root.querySelectorAll('input,select').forEach((el) => el.addEventListener('input', () => {
    updateUI();
    $('regionInfo').innerHTML = translate($('regionInfo').innerHTML);
    if (state.generated) {
      $('output').textContent = '';
      $('count').textContent = '0';
      $('message').textContent = translate('Настройки изменены. Сгенерируйте кейсы заново.');
      state.generated = false;
    }
  }));

  state.root.querySelectorAll('[data-lang]').forEach((button) => button.addEventListener('click', () => {
    state.language = button.dataset.lang;
    refreshLanguage();
    if (state.generated) generate();
  }));

  bindLightbox();
  bindRegionSwitch();
  bindAccountPickers();

  state.root.querySelector('.standalone-account-save').addEventListener('click', saveStandaloneAccounts);
}

// ---- generator/index.js ----------------------------------------------
/** Inputs captured at start so `restore()` can reset every field. */
let workspaceFields = [];
let initialFields = {};

/**
 * Public adapter used by the QA workspace iframe.
 * The contract is unchanged from the legacy generator — the workspace relies
 * on `ready`, `configure`, `snapshot`, `restore` and `cases`.
 */
function installWorkspaceApi() {
  workspaceFields = [...state.root.querySelectorAll('input[data-id],select[data-id],textarea[data-id]')];
  initialFields = Object.fromEntries(workspaceFields.map((el) => [
    el.dataset.id,
    el.type === 'checkbox' ? el.checked : el.value,
  ]));

  window.qaGenerator = {
    configure(hooks) {
      state.workspaceHooks = hooks;
      state.root.querySelector('.standalone-account-save').hidden = true;
      ['output', 'copyAll', 'sendSlack', 'sendSlackExceptFirst'].forEach((id) => {
        const node = state.root.querySelector(`[data-id="${id}"]`);
        if (node) node.hidden = true;
      });
    },
    setAccountOptions,
    loadAccounts,
    syncAccount: syncAccountFields,
    lockRegion(locked) {
      const region = state.root.querySelector('[data-id="region"]');
      if (region) region.disabled = !!locked;
    },
    snapshot() {
      return {
        fields: Object.fromEntries(workspaceFields.map((el) => [
          el.dataset.id,
          el.type === 'checkbox' ? el.checked : el.value,
        ])),
        language: state.language,
        payout_fee_manual: state.payoutFeeManual,
      };
    },
    restore(settings = {}) {
      const fields = { ...initialFields, ...(settings.fields || {}) };
      workspaceFields.forEach((el) => {
        if (el.type === 'checkbox') el.checked = fields[el.dataset.id];
        else el.value = fields[el.dataset.id];
      });
      state.language = settings.language || 'ru';
      state.payoutFeeManual = !!settings.payout_fee_manual;
      state.generated = false;
      const output = state.root.querySelector('[data-id="output"]');
      const count = state.root.querySelector('[data-id="count"]');
      const message = state.root.querySelector('[data-id="message"]');
      if (output) output.textContent = '';
      if (count) count.textContent = '0';
      if (message) message.textContent = '';
      refreshLanguage();
    },
    cases() {
      return [...state.root.querySelectorAll('.case')].map(readCase);
    },
    result() {
      return {
        cases: this.cases(),
        region: state.root.querySelector('[data-id="region"]').value,
      };
    },
    /**
     * Text of the case the generator would produce right now.
     *
     * A hand-written case must start from exactly this block, otherwise the
     * workspace would have to re-implement currency and platform tables that
     * only this module knows. This mirrors the inner half of the generate
     * button, so the text matches what a full generation produces.
     */
    caseText() {
      try {
        state.protectedValues = [];
        state.protectValues = true;
        let cases;
        try {
          cases = generateCases();
        } finally {
          state.protectValues = false;
        }
        const first = cases[0];
        if (!first) return '';
        return localise(first.text, state.protectedValues);
      } catch {
        return '';
      }
    },
  };
}

/** Boot the generator inside its container element. */
function start(root) {
  state.root = root;
  cacheStaticNodes();
  refreshLanguage();
  root.dataset.ready = '1';
  window.qaGenerator.ready = Promise.all([
    loadAccounts().catch(accountError),
  ]);
}

// Re-exported for the workspace adapter and tests.

// ---- generator/main.js -----------------------------------------------
// Browser entry point for the test-case generator.
// Loaded as an ES module; shares behaviour with the legacy inline script but
// keeps state in `store.js` instead of a closure.

const root = document.currentScript?.closest('[data-generator]')
  || Array.from(document.querySelectorAll('[data-generator]')).find((el) => el.dataset.ready !== '1');

if (root && root.dataset.ready !== '1') {
  state.root = root;
  state.accountRegion = root.querySelector('[data-id="region"]').value;
  // `start` needs the static-node cache before the first refresh; the cache
  // itself only walks the DOM, so it is safe to build it here.
  cacheStaticNodes();
  bindEvents();
  installWorkspaceApi();
  start(root);
}
